input.schema:
{
  "type": "record",
  "name": "Date",
  "namespace": "axt",
  "doc": "A calendar date of the proleptic Gregorian calendar, of which a part may be unknown, such as a birthday without a year (null, 5, 3), a year alone (2019, null, null) or a month of a year (2027, 3, null). At least one part is not null, and a day has its month. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "name": "year",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The year, 1 to 9999. Null when the year is not known or does not matter."
    },
    {
      "name": "month",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The month of the year, 1 (January) to 12 (December). Null when the month is not known; then day is null as well."
    },
    {
      "name": "day",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The day of the month, 1 to the number of days of the month: of that year when the year is known, otherwise of a leap year, so that 29 February is valid without a year. Null when the day is not known."
    }
  ]
}

{
  "type": "record",
  "name": "Time",
  "namespace": "axt",
  "doc": "A time of day on the wall clock, to the millisecond, without a date and without a time zone, such as 07:30 for an alarm. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "name": "hour",
      "type": "int",
      "doc": "The hour, 0 to 23."
    },
    {
      "name": "minute",
      "type": "int",
      "doc": "The minute, 0 to 59."
    },
    {
      "name": "second",
      "type": "int",
      "doc": "The second, 0 to 59; a leap second is not written as 60. 0 when the time is given to the minute."
    },
    {
      "name": "millisecond",
      "type": "int",
      "doc": "The millisecond, 0 to 999. 0 when the time is given to the second or the minute."
    }
  ]
}

{
  "type": "record",
  "name": "DateTime",
  "namespace": "axt",
  "doc": "A date and time on the wall clock, to the millisecond, either in a time zone of the IANA time zone database, with the offset from UTC and the instant as the writer's zone rules gave them, or floating, on the wall clock of wherever the user is, without zone, offset and instant. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "name": "year",
      "type": "int",
      "doc": "The year of the proleptic Gregorian calendar, 1 to 9999."
    },
    {
      "name": "month",
      "type": "int",
      "doc": "The month, 1 (January) to 12 (December)."
    },
    {
      "name": "day",
      "type": "int",
      "doc": "The day of the month, 1 to the number of days of that month in that year."
    },
    {
      "name": "hour",
      "type": "int",
      "doc": "The hour on the wall clock, 0 to 23."
    },
    {
      "name": "minute",
      "type": "int",
      "doc": "The minute, 0 to 59."
    },
    {
      "name": "second",
      "type": "int",
      "doc": "The second, 0 to 59; a leap second is not written as 60."
    },
    {
      "name": "millisecond",
      "type": "int",
      "doc": "The millisecond, 0 to 999."
    },
    {
      "name": "zone",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "The name of the time zone in the IANA time zone database, such as Europe/Berlin. Null for a floating time; then offset_seconds and instant_ms are null as well."
    },
    {
      "name": "offset_seconds",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The offset of the wall clock from UTC, in seconds, -64800 to 64800, as the writer's rules of the zone gave it at the instant, such as 3600 for 01:00 east of UTC. Null for a floating time, and only then."
    },
    {
      "name": "instant_ms",
      "type": [
        "null",
        "long"
      ],
      "default": null,
      "doc": "The instant, in milliseconds since 1970-01-01T00:00:00Z without leap seconds: the wall clock read as if it were UTC, minus offset_seconds. Null for a floating time, and only then."
    }
  ]
}

{
  "type": "record",
  "name": "Duration",
  "namespace": "axt",
  "doc": "A length of time in three parts that are not converted into each other: calendar months, calendar days and elapsed milliseconds, as an INTERVAL of SQL. P1M2DT3H is 1 month, 2 days and 10800000 milliseconds; -PT15M is -900000 milliseconds. The parts that are not 0 all have the same sign. Added to a date and time, the months come first, then the days, then the milliseconds. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "name": "months",
      "type": "int",
      "doc": "The number of calendar months, negative for a length back in time. A year is 12 months."
    },
    {
      "name": "days",
      "type": "int",
      "doc": "The number of calendar days, negative for a length back in time. A day on the wall clock, which may last 23 or 25 hours where the offset changes; a week is 7 days."
    },
    {
      "name": "millis",
      "type": "long",
      "doc": "The number of elapsed milliseconds, negative for a length back in time. Hours, minutes and seconds are carried here: an hour is 3600000 milliseconds, and 24 hours are not converted into a day."
    }
  ]
}
